import{_ as a,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"43、【夬】 乾下兑上","description":"周易阐真 - 43、【夬】 乾下兑上","frontmatter":{"title":"43、【夬】 乾下兑上","description":"周易阐真 - 43、【夬】 乾下兑上"},"headers":[],"relativePath":"zh/classics/chanzhen/044.md","filePath":"zh/classics/chanzhen/044.md"}'),s={name:"zh/classics/chanzhen/044.md"};function n(c,p,i,o,h,l){return t(),e("div",null,[...p[0]||(p[0]=[r('<blockquote><p>彖曰：夬，决也，刚决柔也。健而说，决而和。扬于王庭，柔乘五刚也。孚号有厉，其危乃光也。告自邑，不利即戎，所尚乃穷也。利有攸往，刚长乃终也。</p></blockquote><h1 id="_43、【夬】-乾下兑上" tabindex="-1">43、【夬】 乾下兑上 <a class="header-anchor" href="#_43、【夬】-乾下兑上" aria-label="Permalink to “43、【夬】 乾下兑上”">​</a></h1><p>初九：壮于前趾，往不胜，为咎。</p><p>九二：惕号，莫夜有戎，勿恤。</p><p>九三：壮于页1副本，有凶。君子夬，夬独行，遇雨若濡，有愠无咎。</p><p>九四：臀无肤其行，次且牵羊悔亡，闻言不信。</p><p>九五:苋陆夬夬，中行无咎。</p><p>上六：无号，终有凶。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：泽上于天，夬。君子以施禄及下，居德则忌。</p><p>夬者，决也。上兑泽，下乾天，是泽上于天也。泽之水气上升于天，化而为雨，滋润万物，似乎天不自私，决泽下流，夬之象也。</p><p>君子有见于此，知天有泽而万物生，上有泽而下民安。以是施禄及下，使人人皆霑其恩也。但施禄于下者，施其德也。施德不知德，则施之者广，施之者真，亦如天之无物不覆，无物不生。所谓大德不德，与天为配。若知施德为德，是自居其德，其心有私，施禄不久，不为之德，此施禄者之所最忌也。故君子物我同观，施德不望报，有德而不居，其德日大，其心日小，决去一切自满自大之心，亦如泽在天上，降于地下，出于固然也。修道积功累行，行等等方便利人之事，如施禄于人也。但行方便利人之事，多无真心。或图虚名，或图利贿，或应故事，外似利人，内实不利，稍不如意，怨天尤人，此本无德而反居德，何得谓之利人哉?试观天之施泽万物，岂望万物有报乎?不望万物有报，是天有德而不居德。天且不居德，而况常人之德何可居之乎?凡利益于人者，能效天之不居德，而德未有不大者也。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>夬，古快反。莫，音暮。页1副本，音魁。次，七私反。且，七余反。苋，音现。</p><p>夬者，决去也。卦体一阴居于五阳之上，阳将纯而阴将尽，卦德健而和，和以行健，健而不猛，均有以阳去阴之义，故谓夬。此以阳退阴之卦，承上损卦而来。损者，止其悦而不妄悦，所以进阳退阴，以正气而退客气也。客气者，识神所招，欲退客气，莫若先去识神。人自交于后天，识神用事，酒色迷真，财气乱性，情欲俱发，思虑纷生，心君迷惑，习于性成，非一朝一夕之故，岂能斩然决去哉!不能斩然决去，必须从容行事，随时下手，终必识灭。灭而元神复，人心化而道心全，重见本来乾元面目矣。但此识神为人心所恋，欲去识神，莫若先明其心。心若一明，则道心现，而识神易去，故夬扬于王庭也。</p><p>王庭者，心君所居之处，乃分辨邪正之地。心明邪正，则心不为识神所迷，易于去之。但识神用事已久，根深权大，非可冒然下手，必须急缓得法，方能济事。</p><p>曰孚号者，真心实意，以聚正气也。曰有厉者，戒慎恐惧，以防邪气也。曰告自邑者，炼己也。曰不利即戎者，待时也。</p><p>既能聚正气，又能防邪气，更能炼己待时，万缘俱空，只一识神，乘时而决之，未有不利者也。</p><p>卦德健而和，从容不迫，待时下手，其即决阴之妙诀乎?</p><p>初九，在决阴之初，独刚不柔，冒然前进，是壮于前趾矣。前趾之壮，不但不能决阴，而反有以助阴，阳不胜阴，无咎而自致咎。此刚而不谨于决阴者也。</p><p>九二，刚而能柔，儆惕自号，戒备严密，虽莫夜有戎，已伺于未发之先矣。何忧恤之有?此刚而能缓于决阴者也。</p><p>九三，刚躁太过，急欲成功，壮气现之于页1副本，宜有凶道。幸其以正去邪，为君子夬夬之决，但嫌其独刚不柔，其行遇雨，若濡不能遽遂其志而有愠。然行既遇濡，始虽不能刚决，终必和决之，亦可无壮 页1副本 之咎矣。此刚而速于决阴者也。</p><p>九四，刚居不正，道心为人心所累，如臀无肤，其行次且而决阴不果。幸其道心未泯，能以牵引阳气而增长，本有悔而悔可亡。但嫌其不信决阴之言，道心中犹杂人心耳。此刚为柔伤，不知决阴者也。</p><p>九五，切近上阴，阴尊阳卑，道心为人心所瞒，贪恋识神，或决或不决，如苋陆夬夬，一时不能决断其根然。</p><p>夫道心人心所争者，毫发之间，这边是道心，那边是人心，果于决阴，便是道心，不果于决阴，便是人心。心者，神之室，识神与人心相连，故夬夬不定。幸其阳将纯、阴将尽之时，理终胜欲，虽决之不能自然，亦必勉强而能决，是以中于行，而可无咎。此刚为柔牵，勉强决阴者也。</p><p>上六，在决之终，群阴退尽，只有识神一阴未消，其时当决，其势必灭，阳气一进，阴气即化，是以无号终有凶。阴气之无号，即阳气之孚号；阴气之终凶，即阳气之终吉。此阳气纯全、阴气悉化之决者也。</p><p>然则决阴之道，不可太刚，不可太柔，必须刚中有柔，柔中有刚，渐次而决，进一分阳，退一分阴，阳气进全，阴气自化。若不知急缓运用，速欲成功，反助阴气，有伤阳气，阴气终不能退，故退阴之道，须要深明火候耳。</p>',27)])])}const m=a(s,[["render",n]]);export{d as __pageData,m as default};
